import React, { useState } from 'react';

function Books() {
    const[friends,setFriends]=useState([
        {name:'doremon', balance:-70},

    ])

    return (
        <>
           <h1 className='text-center text-warning'> have food ,pay,then split</h1>
            <ul>{
                friends.map((f)=>(
                    <li key={f.name}>
                       {/* {f.name}:{f.balance<0 ? you owe Rs{-f.balance}:f.balance>0 ? rs{f.name} owes you rs{f.balance}:"settled up"} */}
                        <button onClick={()=>setSelectionRange(f.name)}>select</button>  
                    </li>
                ))
                }</ul>
            
            <section>
                <button className='btn btn-white '>add friend</button>
            </section>

        
            <section className='container'>
                {books.map(book => (
                    <div key={book.id} className='row align-items-center border p-3 mb-2'>
                        <div className="col-auto">
                            <input
                                type="checkbox"
                                checked={book.read}
                                onChange={() => toggleRead(book.id)}
                            />
                        </div>
                        <div className="col-md-3">
                            <h5 className='mb-0'>{book.title}</h5>
                            <small className='text-muted'>{book.author}</small>
                        </div>
                        <div className="col-md-3">
                            <button
                                className={`btn ${book.read ? 'btn-secondary' : 'btn-success'} w-100`}
                                onClick={() => toggleRead(book.id)}
                            >
                                {book.read ? 'Mark as Unread' : 'Mark as Read'}
                            </button>
                        </div>
                        <div className="col-md-3">
                            <button
                                className='btn btn-danger w-100'
                                onClick={() => removeBook(book.id)}
                            >
                                Remove from List
                            </button>
                        </div>
                    </div>
                ))}
                {books.length === 0 && (
                    <div className="text-center text-muted">No books added yet.</div>
                )}
            </section>
        </>
    );
}

export default Books;
